from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class ChallengeTemplate:
    slug: str
    title: str
    signature_suffix: str
    task: str
    focus: str
    tests: tuple[str, str, str]
    source_checks: tuple[str, ...] = ()
    time_cap: int = 240


def T(
    slug: str,
    title: str,
    signature_suffix: str,
    task: str,
    focus: str,
    test_1: str,
    test_2: str,
    test_3: str,
    *source_checks: str,
    time_cap: int = 240,
) -> ChallengeTemplate:
    return ChallengeTemplate(
        slug=slug,
        title=title,
        signature_suffix=signature_suffix,
        task=task,
        focus=focus,
        tests=(test_1, test_2, test_3),
        source_checks=source_checks,
        time_cap=time_cap,
    )


